  reference_id    UUID,
  memo            TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE token_transactions IS 'Complete immutable ledger of all token movements';

CREATE INDEX idx_token_transactions_from ON token_transactions(from_agent_did);
CREATE INDEX idx_token_transactions_to ON token_transactions(to_agent_did);
CREATE INDEX idx_token_transactions_type ON token_transactions(transaction_type);
CREATE INDEX idx_token_transactions_token ON token_transactions(token_type);
CREATE INDEX idx_token_transactions_created ON token_transactions(created_at DESC);
CREATE INDEX idx_token_transactions_reference ON token_transactions(reference_id) WHERE reference_id IS NOT NULL;

-- ----------------------------------------------------------------------------
