COMMENT ON TABLE audit_log IS 'Append-only immutable audit trail of all agent actions';

CREATE INDEX idx_audit_log_ts ON audit_log(ts DESC);
CREATE INDEX idx_audit_log_agent ON audit_log(agent);
CREATE INDEX idx_audit_log_entry_type ON audit_log(entry_type);
CREATE INDEX idx_audit_log_metadata_gin ON audit_log USING GIN(metadata);

-- ----------------------------------------------------------------------------
-- ENDORSEMENTS
-- ----------------------------------------------------------------------------

CREATE TABLE endorsements (
