CREATE INDEX idx_sla_records_agent ON sla_records(agent_did);
CREATE INDEX idx_sla_records_compliant ON sla_records(was_compliant) WHERE was_compliant IS NOT NULL;
CREATE INDEX idx_sla_records_recorded ON sla_records(recorded_at DESC);

-- ============================================================================
-- TRIGGERS
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Auto-update updated_at trigger
-- ----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_agents_updated_at
  BEFORE UPDATE ON agents
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trigger_posts_updated_at
  BEFORE UPDATE ON posts
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trigger_collectives_updated_at
  BEFORE UPDATE ON collectives
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trigger_capabilities_updated_at
  BEFORE UPDATE ON capabilities
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trigger_token_balances_updated_at
  BEFORE UPDATE ON token_balances
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trigger_trust_breakdown_updated_at
  BEFORE UPDATE ON agent_trust_breakdown
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- ----------------------------------------------------------------------------
-- Recalculate trust score from breakdown
-- ----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION recalculate_trust_score()
RETURNS TRIGGER AS $$
DECLARE
  computed_score DECIMAL(4,2);
BEGIN
  computed_score := ROUND(
    (NEW.execution_success * 0.35) +
    (NEW.sla_compliance * 0.25) +
    (NEW.peer_endorsements * 0.20) +
    (NEW.audit_transparency * 0.12) +
    (NEW.security_record * 0.08),
    2
  );
  
  UPDATE agents
  SET trust_score = computed_score
  WHERE id = NEW.agent_id;
  
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_recalc_trust_score
  AFTER INSERT OR UPDATE ON agent_trust_breakdown
  FOR EACH ROW EXECUTE FUNCTION recalculate_trust_score();

-- ============================================================================
-- VIEWS
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Agent Leaderboard
-- ----------------------------------------------------------------------------

CREATE VIEW agent_leaderboard AS
SELECT
  a.agent_did,
  a.display_name,
  a.trust_score,
  a.verification_tier,
  a.governance_role,
  COALESCE(
    (SELECT COUNT(*) FROM agent_capabilities ac WHERE ac.agent_id = a.id),
    0
  ) AS capability_count,
  COALESCE(
    (SELECT COUNT(*) FROM endorsements e WHERE e.endorsed_did = a.agent_did),
    0
  ) AS endorsement_count,
  a.created_at
FROM agents a
WHERE a.governance_role != 'BANNED'
ORDER BY a.trust_score DESC, a.created_at ASC;

COMMENT ON VIEW agent_leaderboard IS 'Agent ranking by trust score with key metrics';

-- ----------------------------------------------------------------------------
-- Active Tasks
-- ----------------------------------------------------------------------------

CREATE VIEW active_tasks AS
SELECT
  p.id AS post_id,
  p.title,
  p.author_did,
  t.assignee_did,
  t.deadline,
  t.sla_hours,
  t.bounty_rep,
  p.created_at,
  p.status,
  EXTRACT(EPOCH FROM (t.deadline - NOW())) / 3600 AS hours_remaining
FROM posts p
INNER JOIN tasks t ON p.id = t.post_id
WHERE p.post_type = 'TASK'
  AND p.status = 'ACTIVE'
  AND t.completed_at IS NULL
ORDER BY t.deadline ASC;

COMMENT ON VIEW active_tasks IS 'All open tasks with assignment and deadline information';

-- ----------------------------------------------------------------------------
-- Pending Proposals
-- ----------------------------------------------------------------------------

CREATE VIEW pending_proposals AS
SELECT
  p.id AS post_id,
  p.title,
  p.author_did,
  pr.proposal_type,
  pr.voting_deadline,
  pr.quorum_required,
  pr.pass_threshold,
  pr.votes_for,
  pr.votes_against,
  pr.votes_abstain,
  (pr.votes_for + pr.votes_against + pr.votes_abstain) AS total_votes,
  p.created_at,
  EXTRACT(EPOCH FROM (pr.voting_deadline - NOW())) / 3600 AS hours_remaining
FROM posts p
INNER JOIN proposals pr ON p.id = pr.post_id
WHERE p.post_type = 'PROPOSAL'
  AND p.status = 'ACTIVE'
  AND pr.voting_deadline > NOW()
  AND pr.passed IS NULL
ORDER BY pr.voting_deadline ASC;

COMMENT ON VIEW pending_proposals IS 'Active proposals still in voting window';

